70|fn subvolume_info(file: &File) -> Result<[u8; 504]> {
71|    let mut info = [0u8; 504];
72|    // SAFETY: exact btrfs_ioctl_get_subvol_info_args and a held Btrfs descriptor.
73|    ensure!(unsafe { libc::ioctl(file.as_raw_fd(), 0x81f8_943c as libc::c_ulong, info.as_mut_ptr()) } == 0,
74|        "upgrade subvolume identity unavailable");
75|    Ok(info)
