107|pub(super) fn verify_overlay(
108|    plan: &CleanPlan, image: &File, backing: &std::fs::Metadata, seed_root: &File, guest: &File,
109|) -> Result<Vec<File>> {
110|    let layout = plan.partitioned_overlay.as_ref().context("overlay plan absent")?;
111|    let mounts = Path::new("/var/lib/3tched-leaf-pool/.mounts/3tchedChatbot");
112|    let view_path = mounts.join("root-view");
113|    let view = open_controlled(&view_path, true, Some(&view_path), None)?;
114|    readonly_overlay(&view_path)?;
115|    readonly_overlay(Path::new(&plan.native_root))?;
116|    ensure!(view.metadata()?.dev() == guest.metadata()?.dev()
117|        && view.metadata()?.ino() == guest.metadata()?.ino() && guest.metadata()?.uid() == 1000000,
118|        "Incus root is not the UID-mapped overlay view");
119|    let seed_layer_path = mounts.join("seed-layer");
120|    let seed_layer = open_controlled(&seed_layer_path, true, Some(&seed_layer_path), None)?;
121|    fs_info(&seed_layer, &plan.binding.btrfs_uuid)?;
122|    member_identity(&seed_layer, &plan.members["@"], false)?;
123|    ensure!(seed_layer.metadata()?.dev() == seed_root.metadata()?.dev()
124|        && seed_layer.metadata()?.ino() == seed_root.metadata()?.ino()
125|        && seed_layer.metadata()?.uid() == 1000000, "seed layer is not the mapped inherited @");
126|    let upgrade_path = mounts.join("upgrade");
127|    let upgrade = open(&upgrade_path, true)?;
128|    let upgrade_fs = fs_info(&upgrade, &layout.upgrade_fsid)?;
129|    ensure!(subvolume(&upgrade)? == 5 && upgrade_fs.max_id == 1, "upgrade is not standalone partition storage");
130|    let mut device: DevInfo = unsafe { std::mem::zeroed() }; device.devid = 1;
131|    // SAFETY: exact DEV_INFO ABI and the held upgrade descriptor.
132|    ensure!(unsafe { libc::ioctl(upgrade.as_raw_fd(), 0xd000_941e as libc::c_ulong, &mut device) } == 0,
133|        "upgrade device identity unavailable");
134|    let end = device.path.iter().position(|byte| *byte == 0).context("upgrade device path invalid")?;
135|    let partition = open(Path::new(std::str::from_utf8(&device.path[..end])?), false)?;
136|    let parent = verify_partition(&partition, image, backing, layout, 2)?;
137|    let published_path = upgrade_path.join("@");
138|    let published = open_controlled(&published_path, true, Some(&published_path), None)?;
139|    let upgrade_layer_path = mounts.join("upgrade-layer");
140|    let upgrade_layer = open_controlled(&upgrade_layer_path, true, Some(&upgrade_layer_path), None)?;
141|    fs_info(&published, &layout.upgrade_fsid)?;
142|    fs_info(&upgrade_layer, &layout.upgrade_fsid)?;
143|    ensure!(published.metadata()?.dev() == upgrade_layer.metadata()?.dev()
144|        && published.metadata()?.ino() == upgrade_layer.metadata()?.ino()
145|        && upgrade_layer.metadata()?.uid() == 1000000, "upgrade layer is not the mapped published @");
146|    for layer in [&seed_layer, &upgrade_layer] {
147|        let mut flags: libc::statvfs = unsafe { std::mem::zeroed() };
148|        // SAFETY: held layer descriptor and native statvfs output.
149|        ensure!(unsafe { libc::fstatvfs(layer.as_raw_fd(), &mut flags) } == 0
150|            && flags.f_flag & libc::ST_RDONLY != 0, "overlay layer lost mount read-only protection");
151|    }
152|    let pair_path = Path::new("/var/lib/3tched-leaf-pool/.provisioning/3tchedChatbot.upgrade.json");
153|    let pair = open(pair_path, false)?;
154|    let pair_meta = pair.metadata()?;
155|    ensure!(pair_meta.is_file() && pair_meta.uid() == 0 && pair_meta.mode() & 0o077 == 0
156|        && pair_meta.len() <= 4096, "upgrade pair receipt is not protected and bounded");
157|    let mut bytes = vec![0; pair_meta.len() as usize];
158|    pair.read_exact_at(&mut bytes, 0)?;
159|    let receipt: PairReceipt = serde_json::from_slice(&bytes)?;
160|    ensure!(receipt.phase == "paired" && receipt.direction == "host-to-container"
161|        && receipt.host_fsid == layout.host_upgrade_fsid && receipt.replica_fsid == layout.upgrade_fsid
162|        && !receipt.generation.is_empty() && receipt.generation.len() <= 128
163|        && receipt.generation.bytes().all(|byte| byte.is_ascii_alphanumeric() || byte == b'-'),
164|        "upgrade pair receipt differs from the adoption plan");
165|    let received_path = upgrade_path.join(".upgrade-sync/3tchedChatbot").join(&receipt.generation);
166|    let received = open(&received_path, true)?;
167|    let host_path = Path::new("/var/lib/3tched-leaf-pool/.mounts/host-upgrade/.upgrade-sync/3tchedChatbot")
168|        .join(&receipt.generation);
169|    let host = open(&host_path, true)?;
170|    fs_info(&received, &layout.upgrade_fsid)?;
171|    fs_info(&host, &layout.host_upgrade_fsid)?;
172|    let published_info = subvolume_info(&published)?;
173|    let received_info = subvolume_info(&received)?;
174|    let host_info = subvolume_info(&host)?;
175|    ensure!(u64::from_ne_bytes(received_info[288..296].try_into()?) & 1 != 0
176|        && u64::from_ne_bytes(host_info[288..296].try_into()?) & 1 != 0
177|        && published_info[312..328] == received_info[296..312]
178|        && received_info[328..344] == host_info[296..312], "incremental upgrade baseline ancestry differs");
179|    Ok(vec![view, seed_layer, upgrade, partition, parent, published, upgrade_layer, pair, received, host])
