142|fn fs_info(file: &File, uuid: &str) -> Result<FsInfo> {
143|    // SAFETY: integer-only kernel output with exact asserted ABI size.
144|    let mut info: FsInfo = unsafe { std::mem::zeroed() };
145|    // SAFETY: valid descriptor and correctly sized writable output.
146|    ensure!(
147|        unsafe { libc::ioctl(file.as_raw_fd(), 0x8400_941f as libc::c_ulong, &mut info) } == 0,
148|        "physical Btrfs filesystem query failed"
149|    );
150|    ensure!(
151|        info.fsid == *uuid::Uuid::parse_str(uuid)?.as_bytes()
152|            && info.num_devices == 1
153|            && info.max_id > 0
154|            && info.max_id <= 16,
155|        "physical root is not the pinned single-writable-member filesystem"
156|    );
157|    Ok(info)
158|}
159|
160|fn subvolume(file: &File) -> Result<u64> {
161|    let mut bytes = [0u8; 504];
162|    // SAFETY: buffer matches btrfs_ioctl_get_subvol_info_args.
163|    ensure!(
164|        unsafe {
165|            libc::ioctl(
166|                file.as_raw_fd(),
167|                0x81f8_943c as libc::c_ulong,
168|                bytes.as_mut_ptr(),
169|            )
170|        } == 0,
171|        "physical Btrfs subvolume query failed"
172|    );
173|    Ok(u64::from_ne_bytes(bytes[..8].try_into()?))
174|}
175|
176|fn seed_header(file: &File, fsid: &str, generation: u64) -> Result<()> {
177|    let mut header = [0u8; 80];
178|    file.read_exact_at(&mut header, 65536)?;
179|    ensure!(
180|        header[32..48] == *uuid::Uuid::parse_str(fsid)?.as_bytes()
181|            && u64::from_le_bytes(header[48..56].try_into()?) == 65536
182|            && u64::from_le_bytes(header[64..72].try_into()?) == 0x4d5f_5366_5248_425f
183|            && u64::from_le_bytes(header[56..64].try_into()?) & (1 << 32) != 0
184|            && u64::from_le_bytes(header[72..80].try_into()?) == generation,
185|        "shared physical seed superblock changed"
186|    );
187|    Ok(())
188|}
189|
190|fn loop_matches(info: &LoopInfo, backing: &std::fs::Metadata, readonly: bool) -> bool {
191|    info.device == backing.dev()
192|        && info.inode == backing.ino()
193|        && info.rdevice == backing.rdev()
194|        && info.offset == 0
195|        && info.sizelimit == 0
196|        && info.encrypt_type == 0
197|        && info.encrypt_key_size == 0
198|        && (info.flags & 1 != 0) == readonly
199|}
200|
201|
202|fn member_identity(file: &File, pin: &MemberPin, readonly: bool) -> Result<()> {
203|    let mut bytes = [0u8; 504];
204|    // SAFETY: held Btrfs FD and exact btrfs_ioctl_get_subvol_info_args output.
205|    ensure!(unsafe { libc::ioctl(file.as_raw_fd(), 0x81f8_943c as libc::c_ulong, bytes.as_mut_ptr()) } == 0,
206|        "read inherited subvolume identity");
207|    ensure!(u64::from_ne_bytes(bytes[..8].try_into()?) == pin.id
208|        && bytes[296..312] == *uuid::Uuid::parse_str(&pin.uuid)?.as_bytes()
209|        // GET_SUBVOL_INFO exposes BTRFS_ROOT_SUBVOL_RDONLY (bit 0),
210|        // unlike SUBVOL_GETFLAGS' BTRFS_SUBVOL_RDONLY (bit 1).
211|        && (u64::from_ne_bytes(bytes[288..296].try_into()?) & 1 != 0) == readonly,
212|        "inherited subvolume ID/UUID/protection changed");
213|    Ok(())
214|}
