216|#[repr(C)]
217|#[derive(Clone, Copy)]
218|struct SearchKey {
219|    tree_id: u64, min_objectid: u64, max_objectid: u64, min_offset: u64, max_offset: u64,
220|    min_transid: u64, max_transid: u64, min_type: u32, max_type: u32, nr_items: u32,
221|    unused: u32, unused1: u64, unused2: u64, unused3: u64, unused4: u64,
222|}
223|#[repr(C)]
224|struct SearchArgs { key: SearchKey, buffer: [u8; 3992] }
225|const _: () = assert!(std::mem::size_of::<SearchArgs>() == 4096);
226|
227|fn exact_members(volume: &File, plan: &CleanPlan) -> Result<()> {
228|    let expected = plan.members.values().map(|pin| pin.id).collect::<HashSet<_>>();
229|    let mut seen = HashSet::new();
230|    let mut min_objectid = 256u64;
231|    for _ in 0..16 {
232|        let mut search = SearchArgs { key: SearchKey { tree_id:1, min_objectid, max_objectid:u64::MAX-255, min_offset:0, max_offset:u64::MAX,
233|            min_transid:0, max_transid:u64::MAX, min_type:132, max_type:132, nr_items:32,
234|            unused:0, unused1:0, unused2:0, unused3:0, unused4:0 }, buffer:[0;3992] };
235|        // SAFETY: ABI-sized integer-only search args, held Btrfs descriptor; read-only tree search.
236|        ensure!(unsafe { libc::ioctl(volume.as_raw_fd(), 0xd000_9411 as libc::c_ulong, &mut search) } == 0,
237|            "enumerate inherited subvolumes");
238|        if search.key.nr_items == 0 { ensure!(seen == expected, "filesystem does not contain exactly seven inherited subvolumes"); return Ok(()); }
239|        let mut offset = 0usize; let mut last = None;
240|        for _ in 0..search.key.nr_items {
241|            ensure!(offset + 32 <= search.buffer.len(), "invalid subvolume search output");
242|            let header = &search.buffer[offset..offset+32];
243|            let objectid = u64::from_ne_bytes(header[8..16].try_into()?);
244|            let kind = u32::from_ne_bytes(header[24..28].try_into()?);
245|            let length = u32::from_ne_bytes(header[28..32].try_into()?) as usize;
246|            ensure!(objectid >= min_objectid, "subvolume search moved backwards");
247|            if kind == 132 {
248|                ensure!(expected.contains(&objectid) && seen.insert(objectid), "unexpected or duplicate inherited subvolume");
249|            }
250|            offset = offset.checked_add(32 + length).context("subvolume search overflow")?;
251|            ensure!(offset <= search.buffer.len(), "invalid subvolume search item length");
252|            last = Some(objectid);
253|        }
254|        min_objectid = last.context("empty subvolume page")?.checked_add(1).context("subvolume enumeration overflow")?;
255|    }
256|    anyhow::bail!("subvolume enumeration exceeded bounded budget")
257|}
