259|pub(super) fn verify(plan: &CleanPlan) -> Result<StorageGuard> {
260|    let seed = open(Path::new(&plan.seed_device), false)?;
261|    let leaf = open(Path::new(&plan.binding.device_path), false)?;
262|    let seed_meta = seed.metadata()?; let leaf_meta = leaf.metadata()?;
