2|//! Kernel ABIs match linux/btrfs.h and linux/loop.h; no mount/device mutation.
3|use super::*;
4|#[path = "partitioned.rs"]
5|mod partitioned;
6|use std::path::PathBuf;
7|use nix::libc;
8|use std::{
9|    ffi::CString,
10|    fs::File,
11|    os::{
12|        fd::{AsRawFd, FromRawFd},
13|        unix::fs::{FileExt, FileTypeExt, MetadataExt},
14|    },
15|};
