17|pub(super) struct StorageGuard {
18|    _files: Vec<File>,
19|}
20|
21|#[repr(C)]
22|struct FsInfo {
23|    max_id: u64,
24|    num_devices: u64,
25|    fsid: [u8; 16],
26|    nodesize: u32,
27|    sectorsize: u32,
28|    clone_alignment: u32,
29|    csum_type: u16,
30|    csum_size: u16,
31|    flags: u64,
32|    generation: u64,
33|    metadata_uuid: [u8; 16],
34|    reserved: [u8; 944],
35|}
