37|struct DevInfo {
38|    devid: u64,
39|    uuid: [u8; 16],
40|    bytes_used: u64,
41|    total_bytes: u64,
42|    fsid: [u8; 16],
43|    unused: [u64; 377],
44|    path: [u8; 1024],
45|}
