47|struct LoopInfo {
48|    device: u64,
49|    inode: u64,
50|    rdevice: u64,
51|    offset: u64,
52|    sizelimit: u64,
53|    number: u32,
54|    encrypt_type: u32,
55|    encrypt_key_size: u32,
56|    flags: u32,
57|    file_name: [u8; 64],
58|    crypt_name: [u8; 64],
59|    encrypt_key: [u8; 32],
60|    init: [u64; 2],
61|}
62|const _: () = assert!(std::mem::size_of::<FsInfo>() == 1024);
63|const _: () = assert!(std::mem::size_of::<DevInfo>() == 4096);
64|const _: () = assert!(std::mem::size_of::<LoopInfo>() == 232);
